<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';require_module('budget');require_role(['Administrator','Finance Manager']);
$id=(int)($_GET['id']??0);$token=$_GET['token']??'';if(!$token||!hash_equals(csrf_token(),$token)){http_response_code(419);exit('Invalid CSRF token.');}$s=db()->prepare('SELECT budget_code,approval_status FROM budgets WHERE id=?');$s->execute([$id]);$budget=$s->fetch();if($budget && role_name()==='Finance Manager' && $budget['approval_status']==='Approved'){flash('danger','Approved budgets can only be removed by an Administrator.');redirect('budget/index.php');}$code=$budget['budget_code']??null;if($code){db()->prepare("DELETE FROM approvals WHERE request_type='budget' AND request_id=?")->execute([$id]);db()->prepare('DELETE FROM budgets WHERE id=?')->execute([$id]);log_activity('DELETE','Budget','Deleted '.$code);flash('success','Budget deleted.');}redirect('budget/index.php');
